OUT=~/naive-arm/output
PYTHONPATH=$T:$OUT:$OUT/annotation python3 - <<'EOF'
import json, subprocess
from df import df_syntax_spec
from caruca.ir.syntax import Flag
from InputOutputInfoGeneratorDf import InputOutputInfoGeneratorDf
from ParallelizabilityInfoGeneratorDf import ParallelizabilityInfoGeneratorDf
import os
io = InputOutputInfoGeneratorDf(); io.generate_info(); print("IO calls:", io.calls)
p = ParallelizabilityInfoGeneratorDf(); p.generate_info(); print("parallelizers:", p.parallelizers)

j = json.load(open(os.path.expanduser("~/naive-arm/output/annotation/df.json")))
jflags = {s for e in j["flag"] for s in (e if isinstance(e,list) else [e])}
jopts = {s for e in j["option"] for s in e[:-1]}
opts = df_syntax_spec[0][0]
sflags = {s for n in opts if isinstance(n,Flag) for s in n.spellings()}
sopts = {s for n in opts if not isinstance(n,Flag) for s in n.spellings()}
print("flags only in py:", sflags - jflags - {"--output"}, " only in json:", jflags - sflags)
print("opts only in py:", sopts - jopts, " only in json:", jopts - sopts)

# test every spelling against the real binary
def run(args):
    r = subprocess.run(["/usr/bin/df"]+args, capture_output=True, text=True)
    return r.returncode, (r.stderr.strip().splitlines() or [""])[0]
bad=[]
for s in sorted(sflags):
    if s in ("--help","--version"): continue
    rc,err = run([s,"/"])
    if rc!=0: bad.append((s,err))
for n in opts:
    if isinstance(n,Flag): continue
    val = {"Size":"1M","Filesystem":"ext4","List":"source,target"}[type(n).__name__]
    for s in n.spellings():
        forms = [[s+"="+val]] if n.eq else ([[s,val]] + ([[s+"="+val]] if s.startswith("--") else [[s+val]]))
        for f in forms:
            rc,err = run(f+["/"])
            if rc!=0: bad.append((f,err))
# the fs type one: 'ext4' may not match '/' -> accept "no file systems processed"? check root type
print("failures:", bad)
# Unknown-option sweep: any single-letter option accepted by df but missing from spec?
import string
missing=[]
for c in string.ascii_letters+string.digits:
    rc,err = run(["-"+c,"/"])
    if "invalid option" not in err and "-"+c not in sflags|sopts:
        missing.append(("-"+c,rc,err))
print("accepted short options not in spec:", missing)
EOF
